import {Chess} from './chess.js';
export function replay(fen,history=[]){const c=new Chess(),uci=[];try{for(const san of history){const m=c.move(san);uci.push(m.from+m.to+(m.promotion||''));}if(c.fen()===fen)return {game:c,command:'position startpos'+(uci.length?' moves '+uci.join(' '):'')};}catch{}return {game:new Chess(fen),command:'position fen '+fen};}
export function parseInfo(line){const depth=/\bdepth (\d+)/.exec(line),pv=/\bpv (.+)$/.exec(line),multi=/\bmultipv (\d+)/.exec(line),score=/\bscore (cp|mate) (-?\d+)/.exec(line),nodes=/\bnodes (\d+)/.exec(line);if(!depth||!pv||!score||/\b(lowerbound|upperbound)\b/.test(line))return null;return {depth:+depth[1],rank:multi?+multi[1]:1,kind:score[1],score:+score[2],nodes:nodes?+nodes[1]:0,uci:pv[1].trim().split(/\s+/)};}
export function toCandidate(fen,info){const c=new Chess(fen),pv=[];for(const move of info.uci){const m=c.move({from:move.slice(0,2),to:move.slice(2,4),promotion:move[4]||'q'});pv.push(m.san);}const first=new Chess(fen).move(pv[0]);return {san:first.san,from:first.from,to:first.to,promotion:first.promotion,pv:pv.slice(0,8),score:info.score,scoreKind:info.kind,depth:info.depth||0};}
export function collectResult(fen,groups,expected,bestmove){const complete=[...groups.entries()].filter(([,g])=>Array.from({length:expected},(_,i)=>g.has(i+1)).every(Boolean)).sort((a,b)=>b[0]-a[0]);if(complete.length){const [depth,g]=complete[0];return {fen,engine:'Stockfish 19 lite',depth,nodes:Math.max(...[...g.values()].map(x=>x.nodes)),candidates:Array.from({length:expected},(_,i)=>toCandidate(fen,g.get(i+1)))};}if(bestmove&&!['(none)','0000'].includes(bestmove))return {fen,engine:'Stockfish 19 lite',depth:0,nodes:0,candidates:[toCandidate(fen,{uci:[bestmove],score:0,kind:'cp'})]};return {fen,engine:'Stockfish 19 lite',depth:0,nodes:0,candidates:[]};}
